const approved = 'https://graph.microsoft.com/v1.0/me/messages';
const profile = $('Verify mailbox').first().json;
if ((profile.mail || profile.userPrincipalName || '').toLowerCase() !== 'support@neontrip.de') throw Error('Unexpected Outlook mailbox');
return $input.all().map((item,index) => {
 const state=item.json;
 let url=state.cursor_url;
 if (!url) {
  const filter=state.lane==='recent' ? '&$filter='+encodeURIComponent('lastModifiedDateTime ge '+new Date(state.watermark).toISOString()) : '';
  url=approved+'?$top=100&$select=id,internetMessageId,conversationId,from,sender,toRecipients,ccRecipients,bccRecipients,subject,body,receivedDateTime,sentDateTime,isDraft'+filter;
 }
 if (!url.startsWith(approved+'?')) throw Error('Unexpected Graph cursor');
 return {json:{url,lane:state.lane,revision:state.revision},pairedItem:{item:index}};
});

const account='support@neontrip.de';
const addr = value => (value?.emailAddress?.address || '').trim().toLowerCase();
const list = recipients => [...new Set((recipients || []).map(addr).filter(Boolean))];
return $input.all().map((item,index) => {
 const state=$('Prepare page').itemMatching(index).json;
 const page=item.json;
 if (!Array.isArray(page.value)) throw Error('Missing Outlook page');
 const messages=[];
 for(const mail of page.value) {
  if(mail.isDraft) continue;
  const sender=addr(mail.from)||addr(mail.sender);
  if(!sender) continue;
  const outbound=sender===account;
  if(!outbound && sender.endsWith('@neontrip.de')) continue;
  const recipients=list(mail.toRecipients),cc=list(mail.ccRecipients),bcc=list(mail.bccRecipients);
  const addresses=outbound ? [...new Set([...recipients,...cc,...bcc].filter(e=>!e.endsWith('@neontrip.de')))] : [sender];
  if(!addresses.length) continue;
  if(!mail.id || typeof mail.body?.content!=='string' || mail.body.contentType?.toLowerCase()!=='text') throw Error('Missing full text or immutable ID');
  messages.push({id:mail.id,internet_id:mail.internetMessageId||null,thread:mail.conversationId||null,direction:outbound?'outbound':'inbound',occurred:outbound?mail.sentDateTime:mail.receivedDateTime,sender,recipients,cc,bcc,addresses,subject:mail.subject||'',body:mail.body.content});
 }
 return {json:{p_lane:state.lane,p_revision:state.revision,p_messages:messages,p_next:page['@odata.nextLink']||null},pairedItem:{item:index}};
});
